export const handleValidateAgent = async (
    field: keyof Agent,
    studioPro: StudioProApi,
    agent: Agent
): Promise<true | string> => {
    switch (field) {
        case "model": {
            if (!agent.model) {
                return "Please select a model.";
            }
            const modelDocument = await getCustomBlobDocumentById(studioPro, agent.model);
            if (!modelDocument) {
                return "This document is invalid. Make sure to select a document of type Model.";
            }

            if (modelDocument.excluded) {
                return "The selected model is currently excluded from the project. Please include it to use it as agent's model.";
            }

            break;
        }

        case "entity": {
            if (!agent.entity) {
                if (agent.variables.length > 0) {
                    return "Please select an entity.";
                } else {
                    break;
                }
            }
            const [moduleName, entityDocument] = agent.entity.qualifiedName.split(".");
            if (!moduleName || !entityDocument) {
                return "The selected entity is not valid.";
            }
            const isEntityFound = await isAgentEntityFound(studioPro, agent);
            if (!isEntityFound) {
                return "Entity no longer exists.";
            }
            break;
        }

        case "userPrompt":
            if (!agent.userPrompt) {
                return "Please provide a user prompt.";
            }
            break;

        default:
            return true;
    }
    return true;
};

export const handleShowModel = async (studioPro: StudioProApi, modelDocument: ModelDocument): Promise<void> => {
    if (!modelDocument.documentId) {
        return;
    }
    const model = await getCustomBlobDocumentById(studioPro, modelDocument);
    if (!model) {
        const errorMessage = "Could not find model.";
        const errorDetails = "This model might have been deleted or renamed. Please update the model selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    studioPro.ui.editors.editDocument(modelDocument.documentId);
};

export const handleEditModelSettings = async (
    studioPro: StudioProApi,
    componentName: string,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>
): Promise<Agent | undefined> => {
    const result = await studioPro.ui.dialogs.showModal(
        {
            title: "Model settings",
            contentSize: { height: 400, width: 600 },
        },
        {
            componentName: componentName,
            uiEntrypoint: "modelSettingsEdit",
            queryParams: {
                agent: encodeURIComponent(JSON.stringify(agent)),
            },
        }
    );
    let updatedAgent: Agent | undefined = undefined;
    if (result) {
        updatedAgent = result as Agent;
    }
    if (updatedAgent) {
        updateAgentDocument(updatedAgent);
    }
    return updatedAgent;
};

export const handleEditTool = async (
    studioPro: StudioProApi,
    componentName: string,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>,
    toolId?: string
): Promise<Agent | null> => {
    const tool = toolId && agent.tools ? agent.tools.find((t) => t.id === toolId) : undefined;

    const result = await studioPro.ui.dialogs.showModal(
        {
            title: tool ? "Edit tool" : "Add tool",
            contentSize: { height: 330, width: 600 },
        },
        {
            componentName: componentName,
            uiEntrypoint: "toolEdit",
            queryParams: {
                tool: tool ? encodeURIComponent(JSON.stringify(tool)) : "",
                agent: agent ? encodeURIComponent(JSON.stringify(agent)) : "",
            },
        }
    );

    if (result !== null) {
        const newTool = result as Tool;
        let updatedTools: Tool[];

        if (toolId && agent.tools) {
            // Edit mode: replace the tool with the matching ID
            updatedTools = agent.tools.map((t) => (t.id === toolId ? newTool : t));
        } else {
            // Add mode: add new tool
            updatedTools = [...(agent.tools || []), newTool];
        }

        // Always keep tools sorted by name
        updatedTools.sort((a, b) => a.name.localeCompare(b.name));

        const updatedAgent = { ...agent, tools: updatedTools };
        updateAgentDocument(updatedAgent);
        return updatedAgent;
    } else {
        return null;
    }
};

export const handleDeleteTool = async (
    studioPro: StudioProApi,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>,
    toolId: string
): Promise<Agent | undefined> => {
    const confirmed = await studioPro.ui.messageBoxes.ask({
        type: "confirmation",
        question: "Are you sure you want to delete this tool?",
    });
    if (confirmed === false) {
        return undefined;
    }
    const updatedTools = agent.tools.filter((tool) => tool.id !== toolId);
    const updatedAgent = { ...agent, tools: updatedTools };
    updateAgentDocument(updatedAgent);
    return updatedAgent;
};

export const handleEditKnowledgebaseTool = async (
    studioPro: StudioProApi,
    componentName: string,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>,
    toolId?: string
): Promise<Agent | null> => {
    const knowledgebaseTools = agent.knowledgebaseTools || [];
    const tool = toolId ? knowledgebaseTools.find((t) => t.id === toolId) : undefined;

    const result = await studioPro.ui.dialogs.showModal(
        {
            title: tool ? "Edit knowledge base" : "Add knowledge base",
            contentSize: { height: 541, width: 600 },
        },
        {
            componentName: componentName,
            uiEntrypoint: "knowledgebaseToolEdit",
            queryParams: {
                tool: tool ? encodeURIComponent(JSON.stringify(tool)) : "",
                agent: agent ? encodeURIComponent(JSON.stringify(agent)) : "",
            },
        }
    );

    if (result !== null) {
        const newTool = result as KnowledgebaseTool;
        let updatedKnowledgebaseTools: KnowledgebaseTool[];

        if (toolId) {
            updatedKnowledgebaseTools = knowledgebaseTools.map((t) => (t.id === toolId ? newTool : t));
        } else {
            updatedKnowledgebaseTools = [...knowledgebaseTools, newTool];
        }

        updatedKnowledgebaseTools.sort((a, b) => a.name.localeCompare(b.name));

        const updatedAgent = { ...agent, knowledgebaseTools: updatedKnowledgebaseTools };
        updateAgentDocument(updatedAgent);
        return updatedAgent;
    }

    return null;
};

export const handleDeleteKnowledgebaseTool = async (
    studioPro: StudioProApi,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>,
    toolId: string
): Promise<Agent | undefined> => {
    const confirmed = await studioPro.ui.messageBoxes.ask({
        type: "confirmation",
        question: "Are you sure you want to delete this knowledge base?",
    });
    if (confirmed === false) {
        return undefined;
    }
    const knowledgebaseTools = agent.knowledgebaseTools || [];
    const updatedKnowledgebaseTools = knowledgebaseTools.filter((tool) => tool.id !== toolId);
    const updatedAgent = { ...agent, knowledgebaseTools: updatedKnowledgebaseTools };
    updateAgentDocument(updatedAgent);
    return updatedAgent;
};
