import { StudioProApi } from "@mendix/extensions-api";
import { useCallback, useMemo, useState } from "react";
import styled from "styled-components";

import { AppSelectorNoVersionIcon } from "@mendix/ide-icons/AppSelectorNoVersionIcon";
import { EditIcon } from "@mendix/ide-icons/EditIcon";
import { ErrorIcon } from "@mendix/ide-icons/ErrorIcon";
import { PageIcon } from "@mendix/ide-icons/PageIcon";
import { SyncIcon } from "@mendix/ide-icons/SyncIcon";
import { Checkbox } from "@mendix/ide-ui-components/checkbox/Checkbox";
import { type Selection } from "@mendix/ide-ui-components/table/Table";
import { ToolbarButton } from "@mendix/ide-ui-components/toolbar/ToolbarButton";

import { Agent } from "../../types/agent";
import { ToolValidationState } from "../../types/tool";
import { handleDeleteKnowledgebaseTool, handleEditKnowledgebaseTool } from "./agentHandlers";

import { knowledgebaseIconBase64 } from "../../icons/knowledgebaseIcons";
import GroupBox from "../components/GroupBox";
import IconWrapper from "../components/Icon";
import Table, { useTableSorting } from "../components/Table";
import TextWithIcon from "../components/TextWithIcon";

const StyledCheckbox = styled(Checkbox)`
    pointer-events: auto;
    position: relative;
    z-index: 10;
`;

interface KnowledgebaseToolsTableProps {
    agent: Agent;
    studioPro: StudioProApi;
    componentName: string;
    updateStudioProDocument: (agent: Agent) => Promise<void>;
    onAgentChange: (updatedAgent: Agent) => void;
    knowledgebaseToolValidations: Map<string, ToolValidationState>;
}

const KnowledgebaseToolsTable: React.FC<KnowledgebaseToolsTableProps> = ({
    agent,
    studioPro,
    componentName,
    updateStudioProDocument,
    onAgentChange,
    knowledgebaseToolValidations,
}) => {
    const [selectedToolKeys, setSelectedToolKeys] = useState<Selection>([]);

    const tableData = useMemo(() => {
        const knowledgebaseTools = agent.knowledgebaseTools || [];

        return knowledgebaseTools.map((tool, index) => ({
            id: tool.id ?? String(index),
            enabled: tool.enabled,
            name: tool.name,
            description: tool.description || "",
            tool: tool.document.qualifiedName || "",
        }));
    }, [agent.knowledgebaseTools]);

    const { items, sortProps } = useTableSorting(tableData);

    const getValidationIcon = useCallback(
        (toolId: string) => {
            const state = knowledgebaseToolValidations.get(toolId);
            if (state === "invalid") {
                return <IconWrapper icon={<ErrorIcon title="Tool invalid" />} />;
            } else if (state === "syncing") {
                return <IconWrapper icon={<SyncIcon title="Validating..." />} />;
            }
            return null;
        },
        [knowledgebaseToolValidations]
    );

    const addTool = useCallback(async () => {
        const updatedAgent = await handleEditKnowledgebaseTool(
            studioPro,
            componentName,
            agent,
            updateStudioProDocument
        );
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, componentName, agent, updateStudioProDocument, onAgentChange]);

    const editTool = useCallback(async () => {
        const knowledgebaseTools = agent.knowledgebaseTools || [];
        if (selectedToolKeys.length === 0 || knowledgebaseTools.length === 0) {
            return;
        }

        const selectedToolId = selectedToolKeys[0] as string;
        const updatedAgent = await handleEditKnowledgebaseTool(
            studioPro,
            componentName,
            agent,
            updateStudioProDocument,
            selectedToolId
        );
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, componentName, agent, updateStudioProDocument, onAgentChange, selectedToolKeys]);

    const deleteTool = useCallback(async () => {
        const knowledgebaseTools = agent.knowledgebaseTools || [];
        if (selectedToolKeys.length === 0 || knowledgebaseTools.length === 0) {
            return;
        }

        const selectedToolId = selectedToolKeys[0] as string;
        const updatedAgent = await handleDeleteKnowledgebaseTool(
            studioPro,
            agent,
            updateStudioProDocument,
            selectedToolId
        );
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [agent, updateStudioProDocument, onAgentChange, selectedToolKeys]);

    const setEnabled = useCallback(
        async (toolId: string, isEnabled: boolean) => {
            const knowledgebaseTools = agent.knowledgebaseTools || [];
            if (knowledgebaseTools.length === 0) {
                return;
            }

            const updatedKnowledgebaseTools = knowledgebaseTools.map((tool) =>
                (tool.id ?? "") === toolId ? { ...tool, enabled: isEnabled } : tool
            );
            const updatedAgent = { ...agent, knowledgebaseTools: updatedKnowledgebaseTools };
            updateStudioProDocument(updatedAgent);
            onAgentChange(updatedAgent);
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [agent.knowledgebaseTools, updateStudioProDocument, onAgentChange]
    );

    return (
        <GroupBox label="Knowledge bases">
            <Table
                ariaLabel="Knowledge base tools table"
                columns={[
                    { id: "validation", minWidth: 24, defaultWidth: 24, maxWidth: 24 },
                    {
                        id: "enabled",
                        caption: "Active",
                        isControl: true,
                        minWidth: 63,
                        defaultWidth: 63,
                        maxWidth: 63,
                        allowsSorting: true,
                        alignContents: "center",
                    },
                    { id: "name", caption: "Name", isRowHeader: true, resizable: true, allowsSorting: true },
                    { id: "description", caption: "Description", resizable: true, allowsSorting: true },
                    { id: "knowledgebase", caption: "Knowledge base", resizable: true, allowsSorting: true },
                ]}
                data={items.map((item) => [
                    { cellContent: getValidationIcon(item.id) },
                    {
                        cellContent: (
                            <StyledCheckbox
                                aria-label="Enabled"
                                isSelected={item.enabled}
                                onChange={(isEnabled) => setEnabled(item.id, isEnabled)}
                            />
                        ),
                    },
                    { cellContent: item.name, tooltipText: item.name },
                    { cellContent: item.description, tooltipText: item.description },
                    {
                        cellContent: <TextWithIcon icon={knowledgebaseIconBase64} text={item.tool} />,
                        tooltipText: item.tool,
                    },
                ])}
                rowKey={(_, index) => items[index]?.id ?? String(index)}
                rowOpacity={(index) => (items[index]?.enabled ? 1 : 0.5)}
                selectionType="row"
                selectionMode="single"
                selectedKeys={selectedToolKeys}
                onDoubleClick={editTool}
                onSelectionChange={setSelectedToolKeys}
                {...sortProps}
                toolbarLeft={
                    <>
                        <ToolbarButton
                            icon={<PageIcon />}
                            label="New"
                            aria-label="Add new knowledge base tool"
                            tooltip="Add new knowledge base tool"
                            onPress={addTool}
                        />
                        <ToolbarButton
                            icon={<EditIcon />}
                            label="Edit"
                            aria-label="Edit selected knowledge base tool"
                            onPress={editTool}
                            tooltip="Edit selected knowledge base tool"
                            isDisabled={selectedToolKeys.length === 0}
                        />
                        <ToolbarButton
                            icon={<AppSelectorNoVersionIcon />}
                            label="Delete"
                            aria-label="Delete selected knowledge base tool"
                            onPress={deleteTool}
                            tooltip="Delete selected knowledge base tool"
                            isDisabled={selectedToolKeys.length === 0}
                        />
                    </>
                }
            />
        </GroupBox>
    );
};

export default KnowledgebaseToolsTable;
